"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1374],{64048:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"ResearchGuiController","desc":"Generates the Research Bench GUI entirely in code (no Studio template),\\nopens it via the bench\'s `ResearchPromptPart` ProximityPrompt, and keeps a\\nlocal state cache synced from `ReqResearchSnapshot` + `ResearchStateUpdate`.\\nNode rows are grouped by `Category` (fixed order Train/Player/Equipment/\\nRecipes) and sorted by prereq depth then `DisplayName`; each row lets the\\nplayer enqueue the next level. A queue panel shows the active job (with a\\nMotionMaster-spring-driven progress bar) plus pending jobs, each cancellable.\\nA fuel gauge shows bench fuel (also spring-driven) with a paused badge and\\na Refuel button. While a snapshot\'s authoritative values only change on\\n`ResearchStateUpdate` broadcasts, `interpolated()` fast-forwards the active\\njob\'s elapsed time and fuel locally between broadcasts using the known burn\\nrate + synced server clock, so the bars move smoothly every frame.","realm":["Client"],"source":{"line":19,"path":"src/StarterPlayer/StarterPlayerScripts/ResearchGuiController.client.luau"}}')}}]);